{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.inventory_health_enriched AS WITH po_exceptions AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS sku_group, MAX(CASE WHEN COALESCE(PENDING_QTY, 0) > 0 THEN 1 ELSE 0 END) AS has_open_po, COUNT(DISTINCT ORDER_DATE::DATE) AS inward_count_l360 FROM snitch_db.maplemonk.logic_purchase_order WHERE SKU_GROUP IS NOT NULL AND ORDER_DATE::DATE >= CURRENT_DATE - 360 GROUP BY 1 ), cogs_base AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS sku_group, COST_PRICE AS cogs FROM snitch_db.maplemonk.base_product WHERE SKU_GROUP IS NOT NULL QUALIFY ROW_NUMBER() OVER (PARTITION BY UPPER(TRIM(SKU_GROUP)) ORDER BY COST_PRICE DESC) = 1 ), store_sku_count AS ( SELECT CASE WHEN UPPER(TRIM(sku_group)) LIKE \'SN%\' OR UPPER(TRIM(sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(sku_group)) WHEN UPPER(TRIM(sku_group)) LIKE \'SH%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) WHEN UPPER(TRIM(sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) WHEN UPPER(TRIM(sku_group)) LIKE \'4C%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END END AS sku_group, COUNT(DISTINCT marketplace_mapped) AS store_count FROM snitch_db.maplemonk.offline_master WHERE sku_group IS NOT NULL AND COALESCE(inventory, 0) > 0 GROUP BY 1 ), all_consolidated AS ( SELECT CASE WHEN UPPER(TRIM(sku_group)) LIKE \'SN%\' OR UPPER(TRIM(sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(sku_group)) WHEN UPPER(TRIM(sku_group)) LIKE \'SH%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) WHEN UPPER(TRIM(sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) WHEN UPPER(TRIM(sku_group)) LIKE \'4C%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END END AS sku_group, SUM(COALESCE(xs_units, 0)) AS total_XS, SUM(COALESCE(s_units, 0)) AS total_S, SUM(COALESCE(m_units, 0)) AS total_M, SUM(COALESCE(l_units, 0)) AS total_L, SUM(COALESCE(xl_units, 0)) AS total_XL, SUM(COALESCE(xxl_units, 0)) AS total_2XL, SUM(COALESCE(xl3_units, 0)) AS total_3XL, SUM(COALESCE(xl4_units, 0)) AS total_4XL, SUM(COALESCE(xl5_units, 0)) AS total_5XL, SUM(COALESCE(xl6_units, 0)) AS total_6XL, SUM(COALESCE(xl7_units, 0)) AS total_7XL, SUM(COALESCE(xl8_units, 0)) AS total_8XL FROM snitch_db.maplemonk.offline_master WHERE sku_group IS NOT NULL GROUP BY 1 UNION ALL SELECT sku_group, COALESCE(XS, 0), COALESCE(S, 0), COALESCE(M, 0), COALESCE(L, 0), COALESCE(XL, 0), COALESCE(\"2XL\", 0), COALESCE(\"3XL\", 0), COALESCE(\"4XL\", 0), COALESCE(\"5XL\", 0), COALESCE(\"6XL\", 0), COALESCE(\"7XL\", 0), COALESCE(\"8XL\", 0) FROM snitch_db.maplemonk.inventory_health_final WHERE table_identifier = \'Warehouse\' AND sku_group IS NOT NULL ), all_consolidated_agg AS ( SELECT sku_group, SUM(total_XS) AS total_XS, SUM(total_S) AS total_S, SUM(total_M) AS total_M, SUM(total_L) AS total_L, SUM(total_XL) AS total_XL, SUM(total_2XL) AS total_2XL, SUM(total_3XL) AS total_3XL, SUM(total_4XL) AS total_4XL, SUM(total_5XL) AS total_5XL, SUM(total_6XL) AS total_6XL, SUM(total_7XL) AS total_7XL, SUM(total_8XL) AS total_8XL FROM all_consolidated GROUP BY 1 ) SELECT h.*, c.cogs, h.total_inventory * COALESCE(c.cogs, 0) AS inventory_value, CASE WHEN COALESCE(h.ros_l30, 0) > 0 THEN ROUND(h.total_inventory / h.ros_l30) ELSE NULL END AS doi, CASE WHEN h.ageing IS NULL THEN \'Unknown\' WHEN h.ageing <= 30 THEN \'000-030\' WHEN h.ageing <= 60 THEN \'031-060\' WHEN h.ageing <= 90 THEN \'061-090\' WHEN h.ageing <= 120 THEN \'091-120\' WHEN h.ageing <= 150 THEN \'121-150\' WHEN h.ageing <= 180 THEN \'151-180\' WHEN h.ageing <= 210 THEN \'181-210\' WHEN h.ageing <= 240 THEN \'211-240\' WHEN h.ageing <= 270 THEN \'241-270\' WHEN h.ageing <= 300 THEN \'271-300\' WHEN h.ageing <= 330 THEN \'301-330\' WHEN h.ageing <= 360 THEN \'331-360\' ELSE \'360+\' END AS ageing_bucket, CASE WHEN h.ageing IS NULL THEN 99 WHEN h.ageing <= 30 THEN 1 WHEN h.ageing <= 60 THEN 2 WHEN h.ageing <= 90 THEN 3 WHEN h.ageing <= 120 THEN 4 WHEN h.ageing <= 150 THEN 5 WHEN h.ageing <= 180 THEN 6 WHEN h.ageing <= 210 THEN 7 WHEN h.ageing <= 240 THEN 8 WHEN h.ageing <= 270 THEN 9 WHEN h.ageing <= 300 THEN 10 WHEN h.ageing <= 330 THEN 11 WHEN h.ageing <= 360 THEN 12 ELSE 13 END AS ageing_bucket_sort, COALESCE(po.has_open_po, 0) AS has_open_po, COALESCE(po.inward_count_l360, 0) AS inward_count_l360, CASE WHEN COALESCE(po.has_open_po, 0) = 1 OR COALESCE(po.inward_count_l360, 0) > 1 THEN 1 ELSE 0 END AS po_exception, CASE WHEN COALESCE(h.ageing, 0) > 360 AND h.size_flag = \'cut_size\' AND COALESCE(h.total_inventory, 0) > 0 AND COALESCE(h.ros_l30, 0) < 1 AND COALESCE(po.has_open_po, 0) = 0 AND COALESCE(po.inward_count_l360, 0) <= 1 THEN 1 ELSE 0 END AS is_liquidation, CASE WHEN COALESCE(h.ageing, 0) >= 180 AND COALESCE(h.total_inventory, 0) > 0 AND COALESCE(h.ros_l30, 0) < 5 AND COALESCE(po.has_open_po, 0) = 0 AND COALESCE(po.inward_count_l360, 0) <= 1 AND NOT ( COALESCE(h.ageing, 0) > 360 AND h.size_flag = \'cut_size\' AND COALESCE(h.ros_l30, 0) < 1 ) THEN 1 ELSE 0 END AS is_deep_discount, CASE WHEN h.table_identifier = \'Warehouse\' AND COALESCE(h.full_size_options, 0) >= 1 THEN 1 ELSE 0 END AS is_replenishable, CASE WHEN h.table_identifier = \'Warehouse\' THEN LEAST( COALESCE(h.full_size_options, 0), COALESCE(sc.store_count, 0) ) ELSE NULL END AS max_stores_replenishable, CASE WHEN h.size_flag = \'cut_size\' THEN CASE WHEN h.sku_group LIKE \'%4MBG%\' THEN CASE WHEN GREATEST( LEAST( ROUND((COALESCE(ac.total_3XL, 0) - 1) / 3), ROUND((COALESCE(ac.total_4XL, 0) - 1) / 3), ROUND((COALESCE(ac.total_5XL, 0) - 1) / 2), ROUND((COALESCE(ac.total_6XL, 0) - 1) / 2) ), 0) >= 1 THEN 1 ELSE 0 END ELSE CASE WHEN GREATEST( LEAST( ROUND((COALESCE(ac.total_S, 0) - 2) / 2), ROUND((COALESCE(ac.total_M, 0) - 2) / 4), ROUND((COALESCE(ac.total_L, 0) - 2) / 4), ROUND((COALESCE(ac.total_XL, 0) - 2) / 2) ), 0) >= 1 THEN 1 ELSE 0 END END ELSE NULL END AS can_become_sellable_if_consolidated FROM snitch_db.maplemonk.inventory_health_final h LEFT JOIN cogs_base c ON h.sku_group = c.sku_group LEFT JOIN po_exceptions po ON h.sku_group = po.sku_group LEFT JOIN store_sku_count sc ON h.sku_group = sc.sku_group LEFT JOIN all_consolidated_agg ac ON h.sku_group = ac.sku_group WHERE ( COALESCE(h.total_inventory, 0) > 0 OR COALESCE(h.bad_inv, 0) > 0 OR COALESCE(h.blocked_inv, 0) > 0 OR COALESCE(h.inv_not_synced, 0) > 0 OR COALESCE(h.stock_in_transfer, 0) > 0 OR COALESCE(h.stock_not_found, 0) > 0 OR COALESCE(h.open_purchase, 0) > 0 ) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            